KG42.register("rules-89ad31b2008e83e8e2ce1a3f",{"id":"38-bidirectional_ev_trading::v141-c-R004","paper":"38-bidirectional_ev_trading","record":{"rule_id":"v141-c-R004","mechanism_id":"M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"The customer may sell surplus energy stored in its EV battery to the aggregator during its charging intervals. Scope: Bidirectional energy trading between customers and the aggregator, including the stated Type III EV case. Condition: The customer has a Type III EV with surplus stored battery energy, and the sale occurs during its charging intervals. The customer cannot sell energy to the aggregator; the minimum total energy consumption is zero. Scope: Customer sales to the aggregator in the three-EV-type comparison. Condition: The customer has a Type I or Type II EV. Customer 1 may sell at most 5 kWh to the aggregator in each time slot. Scope: Illustrative Type III EV case for customer 1 in the EV-type performance comparison. Condition: The illustrative Type III scenario and its specified sale bound apply.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Bidirectional energy trading between customers and the aggregator, including the stated Type III EV case. | Customer sales to the aggregator in the three-EV-type comparison. | Illustrative Type III EV case for customer 1 in the EV-type performance comparison.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E03","v141-b-g02-e28","v141-b-g03-E03"]},"x":[{"variable_id":"x_total","symbol":"x_{i,Tot}^t","meaning":"Net total energy consumption of customer i at time-slot t, including both residential appliances and the EV; a negative value means the corresponding amount of energy is sold to the aggregator.","kind":"operational","domain":"Real-valued net energy; may be negative when the customer sells to the aggregator, subject to the EV-type lower bound.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g02-e28"]}],"theta":[{"parameter_id":"theta_xmin_tot","symbol":"x_{i,Tot}^{min,t}","meaning":"Minimum total energy consumption of customer i at time-slot t. Source sets it to zero for Type I or II EVs, which cannot sell energy, and to a negative value for Type III EVs, which can sell stored energy to the aggregator.","value":{"kind":"symbolic","number_value":null,"text_value":"0 for Type I/II EV; \u003c0 for Type III EV"},"unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g02-e28","v141-b-g03-E01"]},{"parameter_id":"theta_xmin_tot_c1","symbol":"x_{1,Tot}^{min,t}","meaning":"Illustrative Type III case lower bound on customer 1's total energy consumption; equivalently, the maximum amount of energy customer 1 may sell to the aggregator is 5 kWh in each time-slot.","value":{"kind":"numeric","number_value":-5.0,"text_value":null},"unit":"kWh","indices":["t"],"evidence_ids":["v141-b-g03-E03"]}],"phi":[{"constraint_id":"v141-c-R004-C001","kind":"mathematical","role":"core","statement":"The customer may sell surplus energy stored in its EV battery to the aggregator during its charging intervals. Scope: Bidirectional energy trading between customers and the aggregator, including the stated Type III EV case. Condition: The customer has a Type III EV with surplus stored battery energy, and the sale occurs during its charging intervals.","expression":"x_{i,Tot}^{min,t} \u003c 0 \\quad \\text{(Type III EV)}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["x_total"],"parameter_refs":["theta_xmin_tot"],"evidence_ids":["v141-b-g01-E03","v141-b-g02-e28"]},{"constraint_id":"v141-c-R004-C002","kind":"mathematical","role":"core","statement":"The customer cannot sell energy to the aggregator; the minimum total energy consumption is zero. Scope: Customer sales to the aggregator in the three-EV-type comparison. Condition: The customer has a Type I or Type II EV.","expression":"x_{i,Tot}^{min,t} = 0 \\quad \\text{(Type I or II EV)}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["x_total"],"parameter_refs":["theta_xmin_tot"],"evidence_ids":["v141-b-g02-e28"]},{"constraint_id":"v141-c-R004-C003","kind":"mathematical","role":"core","statement":"Customer 1 may sell at most 5 kWh to the aggregator in each time slot. Scope: Illustrative Type III EV case for customer 1 in the EV-type performance comparison. Condition: The illustrative Type III scenario and its specified sale bound apply.","expression":"x_{1,Tot}^{min,t} = -5 \\text{ kWh}, \\quad \\forall t \\in \\mathcal{T}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["x_total"],"parameter_refs":["theta_xmin_tot_c1"],"evidence_ids":["v141-b-g03-E03"]}],"pi":[{"evidence_id":"v141-b-g01-E03","location":{"location_id":"src-54c42059a7-p03-c1r4__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"overall energy scheduling of customer i by x = [xi]i∈I, where tri ¯xi = [xti,T ot, xti,App]t∈T . ch ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"We allow the bidirectional energy trading between customers and the aggregator, i.e., each customer can sell its energy to the aggregator when it has surplus energy stored in its EV's battery. Due to the energy trading capability, x_{i,Tot}^t may have a negative value, which means that the corresponding amount of energy is sold to the aggregator. For example, if x_{i,App}^t = 5 kWh and x_{i,Tot}^t = -10 kWh (accordingly x_{i,Tot}^t - x_{i,App}^t = -15 kWh), customer i discharges 15 kWh of energy from its battery to use 5 kWh for its own appliances and to sell 10 kWh to the aggregator at t-th time-slot."},{"evidence_id":"v141-b-g02-e28","location":{"location_id":"src-54c42059a7-p09-c1r3__v141-a-M01-participation","page":9,"printed_page":"1227","section":"VI. Numerical Results","anchor_text":"time slot sch (b) Time varying coefﬁcient at in the wholesale price function. Fig. 3. Demand proﬁles","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"condition"},"source_text":"We consider three types of EVs: • Type I: EV with only a chargeable battery; • Type II: EV with a chargeable and dischargeable battery but no energy trading capability; • Type III: EV with a chargeable and dischargeable battery and bidirectional energy trading capability. If a customer has a Type I or II EV, it cannot sell energy to the aggregator, i.e., x_{i,Tot}^{min,t}=0. On the other hand, if a customer has a Type III EV, it has the capability to sell the stored energy in its EV to the aggregator during its charging intervals, L_i. Hence, in this case, the amount of total energy consumption at time-slot t can have a negative value, i.e., x_{i,Tot}^{min,t}\u003c0. If a customer has an EV with the dischargeable battery (i.e., Type II or III EV), the minimum amount of charged energy during a time-slot can have a negative value, i.e., x_{i,EV}^{min,t}\u003c0. Note that we can regard the case with Type I EV as the reference case with a residential appliance which only consumes energy without discharging capability."},{"evidence_id":"v141-b-g03-E03","location":{"location_id":"src-54c42059a7-p09-c2r2__v141-a-M01-clearing","page":9,"printed_page":null,"section":"VI. Numerical Results","anchor_text":"simple scenario with two customers in a collaborative system. Customer 1 and customer 2 have the dem","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"example"},"source_text":"For all cases, the EV’s battery has a capacity of 30 kWh, i.e., R_1 = 30 kWh, and the maximum amount of charged energy is set to 5 kWh, i.e., x_{1,EV}^{max,t} = 5 kWh, \\forall t \\in \\mathcal{T}. For Type I and II cases, the maximum amount of discharging energy is set to 5 kWh, i.e., x_{1,EV}^{min,t} = -5 kWh, \\forall t \\in \\mathcal{T}. Finally, the maximum amount of energy that the customer with the Type III EV can sell to the aggregator is limited by 5 kWh, i.e., x_{1,Tot}^{min,t} = -5 kWh, \\forall t \\in \\mathcal{T}. In this scenario, we assume that the EV’s initial battery charge level and minimum required battery charge level are 0. The EV is assumed to be connected to the power system during the entire scheduling interval, i.e., \\mathcal{L}_1 = \\{[1,24]\\}."},{"evidence_id":"v141-b-g03-E01","location":{"location_id":"src-54c42059a7-p09-c1r4__v141-a-M01-participation","page":9,"printed_page":null,"section":"VI. Numerical Results","anchor_text":"If a customer has a Type I or II EV, it cannot sell energy to the reg aggregator, i.e., xmin,ti,T ot","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"condition"},"source_text":"If a customer has a Type I or II EV, it cannot sell energy to the aggregator, i.e., x_{i,Tot}^{min,t}=0. On the other hand, if a customer has a Type III EV, it has the capability to sell the stored energy in its EV to the aggregator during its charging intervals, \\mathcal{L}_i. Hence, in this case, the amount of total energy consumption at time-slot t can have a negative value, i.e., x_{i,Tot}^{min,t}\u003c0. If a customer has an EV with the dischargeable battery (i.e., Type II or III EV), the minimum amount of charged energy during a time-slot can have a negative value, i.e., x_{i,EV}^{min,t}\u003c0. Note that we can regard a the case with Type I EV as the reference case with a residential appliance which only consumes energy without discharging capability."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-participation","v141-a-M02-participation"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E03","quote":"We allow the bidirectional energy trading between customers and the aggregator, i.e., each customer can sell its energy to the aggregator when it has surplus energy stored in its EV's battery."},{"evidence_id":"v141-b-g02-e28","quote":"On the other hand, if a customer has a Type III EV, it has the capability to sell the stored energy in its EV to the aggregator during its charging intervals, L_i."}],[{"evidence_id":"v141-b-g02-e28","quote":"If a customer has a Type I or II EV, it cannot sell energy to the aggregator, i.e., x_{i,Tot}^{min,t}=0."}],[{"evidence_id":"v141-b-g03-E03","quote":"Finally, the maximum amount of energy that the customer with the Type III EV can sell to the aggregator is limited by 5 kWh, i.e., x_{1,Tot}^{min,t} = -5 kWh, \\forall t \\in \\mathcal{T}."}]],"C2_formalization":{"graph_sha256":"bf0c2727abd30a84ae26a51584ec1f49248d9c8b92cb666d83ea9f7a46ebf420","applicability":"formalized","reason":"The source supplies explicit lower-bound expressions for x_{i,Tot}^{min,t} by EV type and an illustrative -5 kWh bound for customer 1's Type III case. These are formalized as unary constraints on execution.energy_trade. B evidence remains unreviewed; no independent source audit is claimed.","bindings":[{"object_id":"x_total","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"x_{i,Tot}^t is the operational net energy quantity whose negative value executes a sale to the aggregator. Source g01-E03 defines negative x_{i,Tot}^t as energy sold and g02-e28 links Type III EV capability to negative total energy."},{"object_id":"theta_xmin_tot","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The lower bound x_{i,Tot}^{min,t} determines whether the execution.energy_trade quantity may be negative: source g02-e28/g03-E01 set zero for Type I/II and negative for Type III."},{"object_id":"theta_xmin_tot_c1","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"In the illustrative Type III scenario, source g03-E03 sets customer 1's lower bound x_{1,Tot}^{min,t} to -5 kWh, limiting sale to 5 kWh per time-slot."},{"object_id":"v141-c-R004-C001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formalizes the Type III permission as a negative lower bound on total energy, which allows execution.energy_trade to be negative (sale to the aggregator)."},{"object_id":"v141-c-R004-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formalizes the Type I/II prohibition as a zero lower bound, so execution.energy_trade cannot sell energy to the aggregator."},{"object_id":"v141-c-R004-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formalizes the illustrative customer-1 Type III sale cap as x_{1,Tot}^{min,t}=-5 kWh for every time-slot in the scheduling interval."}],"revision_requests":[]}},"quarantined_references":[]}});
